const {chromium}=require('@playwright/test');
const pairs=[['/','/'],['/capabilities/','/archive/profile/capabilities/'],['/improvements/','/archive/profile/tools/'],['/lean-production/','/lean/'],['/projects/','/notes/'],['/knowledge/','/knowledge/'],['/trust/','/trust/'],['/about/','/about/']];
const selector='main :is(.qily-home-conversion-hero__kicker,.qily-home-conversion-kicker,.qily-ia-kicker,.module-eyebrow,.eyebrow,.hero-eyebrow,.section-kicker,.module-kicker,.kicker,.resource-kicker,.qily-resource-network__kicker,.engineering-kicker,.qily-asset-heading>small,.qily-asset-kicker,.qily-system-axis__title,.qily-home-capability-building__kicker,.qily-home-brand-extension__kicker,.qily-home-conversion-heading>small,.qily-ia-heading>small,.qily-north-kicker)';
async function measure(page,url){await page.goto(url,{waitUntil:'domcontentloaded',timeout:60000});await page.evaluate(()=>document.fonts.ready);await page.waitForTimeout(1700);return await page.evaluate(selector=>[...document.querySelectorAll(selector)].filter(el=>{const r=el.getBoundingClientRect(),s=getComputedStyle(el);return s.display!=='none'&&r.width>0;}).map(el=>{let s=getComputedStyle(el);return {text:el.textContent.replace(/\\s+/g,' ').trim().slice(0,110),cls:el.className,section:el.closest('section')?.id||'',tag:el.tagName,font:s.fontFamily,size:s.fontSize,weight:s.fontWeight,smoothing:s.webkitFontSmoothing,fill:s.webkitTextFillColor,color:s.color,spacing:s.letterSpacing,line:s.lineHeight};}),selector);}
(async()=>{const b=await chromium.launch({headless:true,args:['--no-sandbox']});try{for(const width of [1440,390])for(const [int,cn] of pairs){if(width===390&&!['/','/capabilities/','/knowledge/','/about/'].includes(int))continue;const page=await b.newPage({viewport:{width,height:900}});try{const a=await measure(page,'https://qilylean.com'+int),d=await measure(page,'https://qilylean.cn'+cn);let groups=new Map;for(const x of a){let z=groups.get(x.text)||[];z.push(x);groups.set(x.text,z)}let matched=[];for(const x of d){let ref=(groups.get(x.text)||[]).shift();if(ref){const delta=Object.fromEntries(['font','size','weight','smoothing','fill','color','spacing','line'].filter(p=>x[p]!==ref[p]).map(p=>[p,[ref[p],x[p]]]));matched.push({text:x.text,section:x.section,cls:x.cls,delta});}}console.log('GOLD_AUDIT '+JSON.stringify({width,int,cn,counts:[a.length,d.length],pairs:matched.length,mismatches:matched.filter(x=>Object.keys(x.delta).length),cnUnmatched:d.filter(x=>!a.some(t=>t.text===x.text)).map(x=>({text:x.text,weight:x.weight,smoothing:x.smoothing,cls:x.cls})).slice(0,15)}));}catch(e){console.log('GOLD_AUDIT_ERROR '+JSON.stringify({width,int,cn,error:String(e)}));process.exitCode=1}finally{await page.close()}}}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
